<?php
$mods = ext_all('modules'); $h = '';
foreach ($mods as $id => $m) { $on = ext_is_on($id); $h .= '<tr><td><b>' . h($m['name']) . '</b><br><small class="muted">' . h($m['description']) . '</small></td><td><code>' . h($id) . '</code></td><td>' . h(fa_num($m['version'])) . '</td><td>' . ($m['source'] === 'site' ? 'نصب‌شده در سایت' : 'همراهِ هسته') . '</td><td>' . ($on ? ui_badge('روشن', 'ok') : ui_badge('خاموش')) . '</td><td>' . ui_btn_api($on ? 'خاموش' : 'روشن', 'ext_toggle', ['id' => $id, 'on' => $on ? 0 : 1], ['class' => 'sm']) . '</td></tr>'; }
echo ui_card('ماژول‌ها', ($h ? '<table class="tbl"><tr><th>ماژول</th><th>شناسه</th><th>نسخه</th><th>منبع</th><th>وضعیت</th><th></th></tr>' . $h . '</table>' : '<p class="empty">ماژولی نیست.</p>')
    . '<form class="form" data-api="ext_upload" enctype="multipart/form-data"><div class="grid"><label class="field"><span>نصب از زیپ</span><input type="file" name="zip" accept=".zip" required></label>' . ui_field('kind', ['نوع', 'select', 1, ['modules' => 'ماژول', 'themes' => 'قالب']]) . '</div><div class="actions"><button class="btn">نصب</button></div></form>'
    . '<p class="muted">ماژول‌ها در <code>modules/&lt;id&gt;</code> (همراهِ هسته) یا <code>data/ext/modules/&lt;id&gt;</code> (نصب‌شده در سایت؛ با به‌روزرسانی دست نمی‌خورد) با <code>module.json</code> و <code>main.php</code>. راهنما: docs/modules.md — فروشگاهِ آنلاین هم همین‌طور در <code>modules/shop</code> می‌نشیند.</p>');
$m = theme_mods(); $th = ['' => 'پیش‌فرضِ هسته'] + array_map(fn($t) => $t['name'], ext_all('themes'));
echo ui_card('قالب و ظاهر', ui_form('theme_set', ['id' => ['قالب', 'select', 0, $th], 'primary' => ['رنگِ اصلی', 'color'], 'radius' => ['گردیِ گوشه (px)', 'int'], 'font_size' => ['اندازهٔ قلم (px)', 'int']], ['id' => setting('theme', ''), 'primary' => $m['primary'], 'radius' => $m['radius'], 'font_size' => $m['font_size']], ['after' => ui_btn_api('بازگشت به پیش‌فرض', 'theme_reset', [])]));
$hc = ''; foreach (hooks_catalog() as $k => [$t, $d]) $hc .= '<tr><td><code>' . h($k) . '</code></td><td>' . h($t) . '</td><td>' . h($d) . '</td><td>' . (has_hook($k) ? ui_badge('شنونده دارد', 'ok') : '') . '</td></tr>';
echo ui_card('فهرستِ قلاب‌های هسته', '<table class="tbl">' . $hc . '</table>');
